const $ = s => document.querySelector(s);
const escape = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date = value => value ? new Date(value.length===10?value+'T12:00:00':value).toLocaleString(undefined,{dateStyle:'medium',...(value.length>10?{timeStyle:'short'}:{})}) : 'Not specified';
const labels={on_track:'Reported on track',at_risk:'Reported at risk',blocked:'Reported blocked',unknown:'Unknown',awaiting:'Awaiting response',update_requested:'Update requested',draft:'Draft',live:'Live',closed:'Closed',open:'Assigned',in_progress:'Reported in progress',reported_done:'Reported done',accepted:'Accepted by manager'};
const chip = s => `<span class="chip ${escape(s)}">${escape(labels[s] || s)}</span>`;
const brand = '<div class="brand"><img src="/favicon.svg" alt="">Quick View <small>by Workwork</small></div>';
let state=null, screen='questions', selected=null, authMode='signup', sample=false, requestOpen=null, refreshTimer=null, modalContext=null;
const joinToken=new URLSearchParams(location.hash.slice(1)).get('join');
const initialRoute=location.hash;
if(joinToken) authMode='join';
async function api(path,body,method='POST') {
  const result=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json',...(state?.csrfToken?{'X-CSRF-Token':state.csrfToken}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});
  const data=await result.json();
  if(!result.ok){const error=new Error(data.error || 'Request failed.');error.status=result.status;throw error;}
  return data;
}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500);}
async function refresh(renderPage=true){if(sample)return;if(state){const fresh=await api('/state',undefined,'GET');state=fresh;}if(renderPage)render();}
function person(id){return state.members.find(m=>m.id===id)?.name || 'Unassigned';}
function options(selectedId){const inactive=state.members.find(m=>m.id===selectedId && m.active===false);return '<option value="">Choose a person</option>'+(inactive?`<option value="${escape(inactive.id)}" selected disabled>${escape(inactive.name)} · Inactive — choose someone else</option>`:'')+state.members.filter(m=>m.active!==false).map(m=>`<option value="${escape(m.id)}" ${m.id===selectedId?'selected':''}>${escape(m.name)}${m.id===state.user.id?' (you)':''}</option>`).join('');}
function heading(kicker,title,description=''){return `<p class="eyebrow">${escape(kicker)}</p><h1>${escape(title)}</h1>${description?`<p class="muted">${escape(description)}</p>`:''}`;}
function render(){
  if(!state)return renderAuth();
  const pending=state.requests.filter(r=>r.assigneeId===state.user.id && state.questions.find(q=>q.id===r.questionId)?.status==='live' && !state.briefings.find(b=>b.questionId===r.questionId)?.rows.find(row=>row.requestId===r.id)?.current).length;
  $('#app').innerHTML=`${sample?'<div class="banner"><span>Illustrative sample · Explore a question and its evidence. No real company data.</span><button data-action="exit-sample">Create your company →</button></div>':''}<header>${brand}<nav aria-label="Main navigation"><button data-action="nav" data-screen="questions" class="${screen==='questions'?'active':''}">${state.user.role==='manager'?'Owner desk':'Questions'}</button><button data-action="nav" data-screen="requests" class="${screen==='requests'?'active':''}">My requests${pending?' · '+pending:''}</button><button data-action="nav" data-screen="team" class="${screen==='team'?'active':''}">Team</button></nav><div class="account"><div><strong>${escape(state.company.name)}</strong><span class="muted">${escape(state.user.name)}</span></div><button class="light small" data-action="${sample?'exit-sample':'logout'}">${sample?'Exit sample':'Sign out'}</button></div></header><main class="page">${screen==='team'?teamPage():screen==='requests'?requestsPage():selected?questionPage():questionsPage()}<footer>${escape(state.planning.label)} · Evidence stays within your company workspace. <button class="link small" data-action="refresh">Refresh</button></footer></main>`;
}
function renderAuth(){
  $('#app').innerHTML=`<header>${brand}<span class="fine muted">A clear answer starts with the right question.</span></header><main class="hero"><section class="hero-copy"><p class="eyebrow">For manufacturing owners</p><h1>Ask your company.<br>Close the loop.</h1><p>Which deliveries need your decision? Get focused answers from your team, assign the next step, and see the reported result—with the source evidence attached.</p><button data-action="sample">Explore a sample briefing ↗</button><div class="hero-steps"><span><b>01 / ASK</b>Set the question</span><span><b>02 / CONNECT</b>Hear from your team</span><span><b>03 / FOLLOW THROUGH</b>Decide and review the result</span></div></section><section class="auth-wrap"><div class="auth-card">${authMode!=='join'?`<div class="auth-tabs"><button class="${authMode==='signup'?'active':''}" data-action="auth-mode" data-mode="signup">Create a company</button><button class="${authMode==='login'?'active':''}" data-action="auth-mode" data-mode="login">Sign in</button></div>`:''}<h2>${authMode==='signup'?'Start with one question.':authMode==='join'?'Join your company.':'Welcome back.'}</h2><p class="muted fine">${authMode==='signup'?'Create your own workspace, then invite the people who have the answers.':authMode==='join'?'Your invitation connects you to your team’s workspace.':'Sign in to your Quick View workspace.'}</p><form data-form="auth" class="fields">${authMode==='signup'?'<label>Company name<input name="companyName" required maxlength="120" autocomplete="organization" placeholder="Your company"></label>':''}${authMode!=='login'?'<label>Your name<input name="name" required maxlength="120" autocomplete="name" placeholder="Full name"></label>':''}${authMode!=='join'?'<label>Work email<input name="email" type="email" required maxlength="254" autocomplete="email" placeholder="you@company.com"></label>':''}<label>Password<input name="password" type="password" required minlength="12" maxlength="256" autocomplete="${authMode==='login'?'current-password':'new-password'}"><span class="helper">At least 12 characters. Use a password unique to this service.</span></label><button class="primary" type="submit">${authMode==='signup'?'Create workspace →':authMode==='join'?'Join workspace →':'Sign in →'}</button><div class="form-message" role="alert"></div></form><p class="fine muted spaced">Independent Quick View pilot. Existing Workwork accounts are separate. Company questions and responses are shared with your workspace members.</p></div></section></main>`;
}
function brief(id){
  const b=state.briefings.find(b=>b.questionId===id) || {rows:[],answered:0,total:0,attention:[],unknown:[],decisions:[]};
  const actions=b.actions || (state.actions || []).filter(a=>a.questionId===id);
  return {...b,actions,openActions:b.openActions || actions.filter(a=>a.status!=='accepted'),overdueActions:b.overdueActions || actions.filter(isOverdue),needsRecheck:b.needsRecheck || [],earlierConcerns:b.earlierConcerns || [],decisionRequests:b.decisionRequests || b.rows.filter(row=>row.response?.decisionNeeded && !(b.decisions || []).some(d=>(d.responseIds || []).includes(row.response.id)))};
}
function isOverdue(a){return a.status!=='accepted' && a.dueDate && a.dueDate<new Date().toISOString().slice(0,10);}
function freshness(row){
  if(!row.response)return '';
  const labels={recent:'Within review window',aging:'Recheck due',undated:'Observation date missing',future:'Check future observation date',missing:'No evidence yet'};
  return `<span class="freshness ${escape(row.freshness || 'undated')}">${escape(labels[row.freshness] || 'Observation date missing')}${Number.isFinite(row.ageDays)?' · '+Math.floor(row.ageDays)+'d':''}</span>`;
}
function changeLabel(row){return ({first:'First response',reconfirmed:'Rechecked · no change',updated:'Updated response',unchanged:'Same content · resubmitted',awaiting:'Awaiting response'})[row.changeKind] || (row.response?'Recorded response':'Awaiting response');}
function freshnessField(q={}){return `<label>Recheck evidence after (days)<input type="number" name="freshnessDays" min="1" max="90" required value="${Number(q.freshnessDays) || 7}"><span class="helper">Based on observation or explicit recheck time. This is a review policy.</span></label>`;}
const starters=[
  ['Friday deliveries','Can we deliver this Friday’s orders on time? What needs my decision?'],
  ['Production readiness','Is the new production line ready to start? What remains unconfirmed?'],
  ['품질 문제','이번 주 반복되는 품질 문제는 무엇이고, 제가 결정해야 할 것은 무엇인가요?'],
  ['이번 주 납기','이번 주 납기를 지킬 수 있나요? 지연 위험과 필요한 결정을 알려주세요.']
];
function deskExceptions(){
  const live=state.questions.filter(q=>q.status==='live').map(q=>({q,b:brief(q.id)}));
  const decisions=live.flatMap(({q,b})=>b.decisionRequests.map(row=>({q,row})));
  const checks=live.flatMap(({q,b})=>b.needsRecheck.map(row=>({q,row})));
  const actions=(state.actions || []).filter(a=>a.status!=='accepted').sort((a,b)=>Number(isOverdue(b))-Number(isOverdue(a)));
  const gaps=state.assignmentGaps || {requests:[],actions:[]};
  const gapNotice=(gaps.requests.length || gaps.actions.length)?`<section class="notice assignment-notice spaced"><strong>Some work needs an active responsible person.</strong><p>These assignments belong to inactive members. Their history remains available.</p><div class="row">${gaps.requests.map(id=>{const r=state.requests.find(r=>r.id===id);return r?`<button class="link small" data-action="request" data-id="${id}">Reassign request: ${escape(r.title)} →</button>`:'';}).join('')}${gaps.actions.map(id=>{const a=(state.actions || []).find(a=>a.id===id);return a?`<button class="link small" data-action="action-detail" data-id="${id}">Reassign action: ${escape(a.title)} →</button>`:'';}).join('')}</div></section>`:'';
  if(!state.questions.some(q=>q.status!=='draft') && !actions.length)return '';
  return gapNotice+`<div class="desk-grid"><section class="card exception-card"><div class="section-head"><h2>Needs your decision</h2><span class="count">${decisions.length}</span></div>${decisions.length?decisions.slice(0,4).map(({q,row})=>`<article class="desk-item"><span class="fine muted">${escape(q.text)}</span><p>${escape(row.response.decisionNeeded)}</p>${!row.current?'<span class="fine pending-refresh">Earlier request · update pending</span>':''}<div class="row"><button class="link small" data-action="decide" data-question="${q.id}" data-response="${row.response.id}">Decide & assign →</button><button class="link small" data-action="request" data-id="${row.requestId}">Evidence</button></div></article>`).join(''):'<p class="muted fine">No unanswered decision requests in live questions. Other information may still be missing.</p>'}${decisions.length>4?'<p class="fine muted">More requests are available in the question briefings below.</p>':''}</section><section class="card exception-card"><div class="section-head"><h2>Evidence to recheck</h2><span class="count">${checks.length}</span></div>${checks.length?checks.slice(0,4).map(({q,row})=>`<article class="desk-item"><strong>${escape(row.title)}</strong><p class="fine muted">${escape(q.text)}</p>${freshness(row)}<div><button class="link small" data-action="request" data-id="${row.requestId}">${escape(person(row.assigneeId))} · Review evidence →</button></div></article>`).join(''):'<p class="muted fine">No current evidence is flagged for recheck. Unanswered requests remain unknown.</p>'}${checks.length>4?'<p class="fine muted">Open a question below to review the remaining evidence.</p>':''}</section><section class="card exception-card"><div class="section-head"><h2>Follow-through</h2><span class="count">${actions.length}</span></div>${actions.length?actions.slice(0,4).map(a=>actionCard(a,true)).join(''):'<p class="muted fine">Decisions with an assigned next step will appear here until accepted by a manager.</p>'}${actions.length>4?'<p class="fine muted">More assigned actions are available in their question briefings.</p>':''}</section></div>`;
}
function questionsPage(){
  const manager=state.user.role==='manager',sorted=[...state.questions].reverse();
  return `${heading(manager?'Owner desk':'Company questions',manager?'What needs your attention?':'The questions we’re answering.',manager?'Decide on the exceptions. See what changed and what happened next.':'Shared questions, team responses and decisions in one place.')}${manager?deskExceptions():''}${manager?`<form data-form="ask" class="card composer"><p class="eyebrow">Start a focused check-in</p><label><span class="sr-label">Your question</span><textarea class="main-question" name="text" required maxlength="1200" placeholder="Can we deliver Friday’s orders on time? What needs my attention?" rows="3"></textarea></label><div class="starters">${starters.map(([label],i)=>`<button type="button" class="light small" data-action="starter" data-index="${i}">${escape(label)}</button>`).join('')}</div><details><summary class="fine muted">Add scope, deadline or evidence review policy</summary><div class="two spaced"><label>Scope and useful context<textarea name="context" maxlength="3000" rows="2" placeholder="Which orders, project or period? What decision will this help you make?"></textarea></label><div class="fields"><label>Responses needed by<input name="dueDate" type="date"></label>${freshnessField()}</div></div></details><div class="row"><span class="fine muted">${state.planning.externalProcessing?'AI drafts the breakdown. You review before assigning.':'Guided draft → review → assign. English or Korean questions welcome.'}</span><button type="submit" class="primary">Build a response plan →</button></div>${state.planning.externalProcessing?'<p class="fine muted spaced">Your question and context will be sent to the configured AI provider for drafting.</p>':''}<div class="form-message" role="alert"></div></form>`:''}<div class="section-head"><h2>Your questions <span class="muted">${sorted.length}</span></h2><span class="fine muted">${sorted.filter(q=>q.status==='live').length} live · ${sorted.filter(q=>q.status==='draft').length} drafts</span></div>${sorted.length?`<div class="question-list">${sorted.map(q=>{const b=brief(q.id);return `<button class="card question-card" data-action="question" data-id="${q.id}"><div><h3>${escape(q.text)}</h3><div class="meta">${chip(q.status)}${q.round>1?`<span>Check-in ${q.round}</span>`:''}<span>${q.status==='draft'?'Ready for your review':b.answered+' / '+b.total+' responses'}</span>${b.decisionRequests.length?`<span class="emphasis">${b.decisionRequests.length} decision request${b.decisionRequests.length===1?'':'s'}</span>`:''}${b.openActions.length?`<span>${b.openActions.length} follow-through open</span>`:''}${q.dueDate?`<span>Due ${date(q.dueDate)}</span>`:''}</div></div><span class="arrow" aria-hidden="true">↗</span></button>`;}).join('')}</div>`:`<div class="empty"><h3>${manager?'One real question is enough to start.':'Your team’s questions will appear here.'}</h3><p>${manager?'Choose a delivery, readiness or quality question. Review the plan before assigning it.':'Your manager can assign a focused request to you.'}</p></div>`}`;
}
function questionPage(){
  const q=state.questions.find(q=>q.id===selected);if(!q){selected=null;return questionsPage();}
  const requests=state.requests.filter(r=>r.questionId===q.id),b=brief(q.id),manager=state.user.role==='manager';
  const head=`<div class="section-head"><button class="link" data-action="back">← All questions</button><div class="row">${chip(q.status)}${manager && q.status!=='draft'?`<button class="light small" data-action="check-in" data-id="${q.id}">Start next check-in</button><button class="link small" data-action="transition" data-transition="${q.status==='closed'?'reopen':'close'}" data-id="${q.id}">${q.status==='closed'?'Reopen':'Close question'}</button>`:''}</div></div>${heading('Question / '+(q.status==='draft'?'plan':`check-in ${q.round || 1}`),q.text)}<div class="meta"><span>Asked by ${escape(q.authorName)}</span><span>${date(q.createdAt)}</span>${q.dueDate?`<span>Responses due ${date(q.dueDate)}</span>`:''}${q.previousQuestionId?`<button class="link small" data-action="question" data-id="${q.previousQuestionId}">Previous check-in ↗</button>`:''}</div>${q.context?`<p class="muted pre spaced">${escape(q.context)}</p>`:''}`;
  if(q.status==='draft')return head+`<div class="draft-banner"><strong>A draft, ready for your judgment.</strong><p class="fine spaced">${escape(q.planNote)} Nothing is assigned until you launch.${q.previousQuestionId?' Review each prompt for the new scope. Earlier answers stay in the previous check-in.':''}</p></div><form data-form="plan" data-id="${q.id}" data-version="${q.version}"><div class="two"><label>Context / scope<textarea name="context" maxlength="3000" rows="3">${escape(q.context)}</textarea></label><div class="fields"><label>Responses needed by<input type="date" name="dueDate" value="${escape(q.dueDate)}"></label>${freshnessField(q)}</div></div><div class="section-head"><h2>Who can answer each part?</h2><button type="button" class="light small" data-action="add-request">+ Add a request</button></div><div class="plan-grid" id="plan-requests">${requests.map((r,i)=>planCard(r,i)).join('')}</div><div class="form-message" role="alert"></div><div class="draft-actions"><button type="submit" name="intent" value="save" class="light">Save draft</button><button type="submit" name="intent" value="launch" class="primary">Launch team requests →</button></div><p class="fine muted">Requests appear in each person’s in-app inbox. You can assign yourself to try the workflow. Invite colleagues from Team.</p></form>`;
  return head+`<div class="brief-tools"><span class="fine muted">Recheck after ${q.freshnessDays || 7} days · Uses observation or explicit recheck time</span><div class="row"><button class="light small" data-action="copy-briefing" data-id="${q.id}">Copy briefing</button><button class="light small" data-action="copy-link" data-kind="question" data-id="${q.id}">Copy question link</button></div></div><div class="summary-grid"><div class="brief-intro"><p class="eyebrow">The picture so far</p><h2>${escape(b.headline || 'Waiting for the team’s evidence.')}</h2><p>${b.answered} of ${b.total} responses received. Reporting coverage is not business performance.</p></div><div class="stats"><div class="stat"><b>${b.decisionRequests.length}</b><span>Decision requests</span></div><div class="stat"><b>${new Set([...b.needsRecheck,...b.unknown].map(row=>row.requestId)).size}</b><span>Recheck or missing</span></div><div class="stat"><b>${b.openActions.length}</b><span>Follow-through open</span></div></div></div><div class="brief-layout"><section><div class="card"><div class="section-head"><h2>Decisions needed</h2>${manager?`<button class="link small" data-action="decide" data-question="${q.id}">+ Record a decision</button>`:''}</div>${b.decisionRequests.length?b.decisionRequests.map(row=>`<article class="attention-item"><div class="row"><strong>${escape(row.title)}</strong>${!row.current?'<span class="chip update_requested">Earlier request · update pending</span>':''}</div><p>${escape(row.response.decisionNeeded)}</p><span class="fine muted">${escape(row.response.authorName)} · ${date(row.response.createdAt)}</span><div class="row spaced">${manager?`<button class="primary small" data-action="decide" data-question="${q.id}" data-response="${row.response.id}">Decide & assign →</button>`:''}<button class="link small" data-action="request" data-id="${row.requestId}">Inspect evidence</button></div></article>`).join(''):'<p class="fine muted">No unresolved decision request is recorded. Information gaps below may still prevent an answer.</p>'}</div><div class="card spaced"><div class="section-head"><h2>Follow-through</h2><span class="fine muted">${b.openActions.length} not yet accepted</span></div>${b.actions.length?b.actions.map(a=>actionCard(a)).join(''):'<p class="fine muted">Assign a next step when recording a decision. Its updates and outcome will stay connected here.</p>'}<p class="fine muted spaced">Reported completion and manager acceptance are distinct. Neither establishes a business KPI result.</p></div></section><aside><section class="card"><h2>What still needs attention</h2>${b.attention.length?b.attention.map(row=>`<div class="attention-item"><strong>${escape(row.title)}</strong><div class="spaced">${chip(row.state)} ${freshness(row)}</div><p>${escape(row.response.nextStep || row.response.text)}</p><button class="link small" data-action="request" data-id="${row.requestId}">View current response →</button></div>`).join(''):'<p class="fine muted">No current response flags a risk or asks for a decision.</p>'}${b.earlierConcerns.map(row=>`<div class="attention-item"><strong>${escape(row.title)}</strong><p class="pending-refresh">Earlier concern — update requested</p><p>${escape(row.response.text)}</p><button class="link small" data-action="request" data-id="${row.requestId}">See earlier evidence →</button></div>`).join('')}${b.unknown.length?`<h3 class="spaced">Missing answers</h3>${b.unknown.map(row=>`<div class="desk-item"><strong class="fine">${escape(row.title)}</strong><p class="fine muted">${escape(person(row.assigneeId))} · ${escape(labels[row.state] || row.state)}</p><button class="link small" data-action="request" data-id="${row.requestId}">Open request</button></div>`).join('')}`:''}${b.needsRecheck.length?`<h3 class="spaced">Recheck evidence</h3>${b.needsRecheck.map(row=>`<div class="desk-item"><strong class="fine">${escape(row.title)}</strong><div>${freshness(row)}</div><button class="link small" data-action="request" data-id="${row.requestId}">Review date & evidence →</button></div>`).join('')}`:''}</section></aside></div><div class="flow-label">Responses / changes and sources</div><div class="flow-grid">${b.rows.map(row=>requestCard(row,requests.find(r=>r.id===row.requestId))).join('')}</div><div class="flow-foot">Response requests feed this briefing. Their order does not establish an operating process.</div><details class="card evidence-details"><summary>All reported evidence · ${b.answered} current responses</summary><div class="spaced">${b.rows.filter(r=>r.response).map(evidenceBlock).join('') || '<p class="muted fine">No recorded responses yet.</p>'}</div><div class="notice spaced">${escape(b.note || 'Team statements are not independently verified.')}</div></details><section class="card spaced"><h2>Decision history</h2>${b.decisions.length?b.decisions.map(d=>`<div class="decision"><p>${escape(d.text)}</p><span class="fine muted">${escape(d.authorName)} · ${date(d.createdAt)}</span>${(d.responseIds || []).map(id=>{const a=state.responses.find(r=>r.id===id);return a?`<div><button class="link small" data-action="evidence" data-response="${id}">Source response · ${escape(a.authorName)} · ${date(a.createdAt)} ↗</button></div>`:'';}).join('')}</div>`).join(''):'<p class="fine muted">No decision has been recorded.</p>'}</section>`;
}
function planCard(r,i){return `<section class="card plan-card"><input type="hidden" data-field="id" value="${escape(r.id || '')}"><div class="row"><span class="number">${i+1}</span><button type="button" data-action="remove-request" class="link small">Remove</button></div><div class="fields"><label>Area<input data-field="title" value="${escape(r.title)}" required maxlength="120"></label><label>Suggested function<input data-field="role" value="${escape(r.role)}" maxlength="100"></label><label>Question to answer<textarea data-field="prompt" rows="4" required maxlength="1500">${escape(r.prompt)}</textarea></label><label>Responsible person<select data-field="assigneeId">${options(r.assigneeId)}</select></label></div></section>`;}
function requestCard(row,r){return `<article class="card flow-card ${escape(row.state)}"><div>${chip(row.state)}</div><h3>${escape(r.title)}</h3><span class="fine muted">${escape(person(r.assigneeId))} · ${escape(changeLabel(row))}</span><p>${escape(row.response ? (row.current?'':'Earlier response: ')+row.response.text.slice(0,160)+(row.response.text.length>160?'…':'') : 'A focused question is waiting for its responsible person.')}</p>${freshness(row)}<div class="row spaced"><button class="link small" data-action="request" data-id="${r.id}">${r.assigneeId===state.user.id && !row.current?'Respond →':'Open response ↗'}</button><span class="fine muted">${row.historyCount?row.historyCount+' update'+(row.historyCount===1?'':'s'):''}</span></div></article>`;}
function responseBody(a){return `<p class="pre">${escape(a.text)}</p><p class="source fine muted">${escape(a.authorName)} · Recorded ${date(a.createdAt)}<br>Observed: ${date(a.observedAt)}${a.confirmedAt?`<br>Explicitly rechecked: ${date(a.confirmedAt)}`:''}<br>Source reference: ${escape(a.source || 'Team statement · no additional reference')}</p>${a.nextStep?`<p class="fine pre"><strong>Next step:</strong> ${escape(a.nextStep)}</p>`:''}${a.decisionNeeded?`<p class="fine pre"><strong>Decision requested:</strong> ${escape(a.decisionNeeded)}</p>`:''}${a.reconfirmedResponseId?'<p class="fine muted">Reconfirmation preserves the earlier observation date and source. The named author explicitly rechecked applicability.</p>':''}${a.reused?`<p class="fine muted">Adapted from ${escape(a.reused.authorName)}’s response recorded ${date(a.reused.createdAt)}.</p>`:''}`;}
function evidenceBlock(row){return `<div class="evidence"><div class="row"><strong>${escape(row.title)}</strong>${chip(row.state)}${freshness(row)}</div><p class="fine muted">${escape(changeLabel(row))}</p>${responseBody(row.response)}${!row.current?'<p class="pending-refresh">A follow-up is awaiting a new answer. This earlier response remains context.</p>':''}<button class="link small" data-action="request" data-id="${row.requestId}">View evidence & history ↗</button></div>`;}
function actionCard(a,compact=false){return `<article class="${compact?'desk-item':'action-card'}"><div class="row"><strong>${escape(a.title)}</strong>${chip(a.status)}${isOverdue(a)?'<span class="chip at_risk">Past due date</span>':''}</div>${!compact?`<p class="fine pre spaced">Expected result: ${escape(a.expectedResult)}</p>`:''}<p class="fine muted">${escape(person(a.assigneeId))}${a.dueDate?' · Due '+date(a.dueDate):''}</p><button class="link small" data-action="action-detail" data-id="${a.id}">${a.status==='reported_done' && state.user.role==='manager'?'Review reported result →':'View action & updates →'}</button></article>`;}
function requestsPage(){
  const mine=state.requests.filter(r=>r.assigneeId===state.user.id && state.questions.find(q=>q.id===r.questionId)?.status==='live');
  const pending=mine.filter(r=>!brief(r.questionId).rows.find(row=>row.requestId===r.id)?.current),answered=mine.filter(r=>!pending.includes(r));
  const actions=(state.actions || []).filter(a=>a.assigneeId===state.user.id);
  const requestItem=r=>{const q=state.questions.find(q=>q.id===r.questionId),row=brief(q.id).rows.find(row=>row.requestId===r.id);return `<article class="card"><p class="fine muted">${escape(q.text)}</p><div class="section-head"><h2>${escape(r.title)}</h2>${chip(row.state)}</div><p class="pre">${escape(r.prompt)}</p>${(r.followups || []).length?`<div class="followup"><strong>Latest follow-up:</strong> ${escape(r.followups.at(-1).text)}</div>`:''}${freshness(row)}<div class="row spaced"><button class="primary" data-action="request" data-id="${r.id}">${row.current?'Review / recheck':'Respond →'}</button><button class="link" data-action="question" data-id="${q.id}">Full question</button>${q.dueDate?`<span class="fine muted">Due ${date(q.dueDate)}</span>`:''}</div></article>`;};
  return `${heading('Your part of the answer','What needs your update?','Answer focused questions. Recheck what still applies. Keep the next step visible.')}<div class="section-head"><h2>Needs your response <span class="muted">${pending.length}</span></h2></div><div class="question-list">${pending.length?pending.map(requestItem).join(''):'<div class="empty">No unanswered live requests are assigned to you.</div>'}</div><div class="section-head"><h2>Your follow-through <span class="muted">${actions.filter(a=>a.status!=='accepted').length}</span></h2></div><section class="card">${actions.filter(a=>a.status!=='accepted').map(a=>actionCard(a)).join('') || '<p class="fine muted">No open assigned actions. Actions remain visible even when their question closes.</p>'}</section>${answered.length?`<details class="spaced"><summary>Responses already provided · ${answered.length}</summary><div class="question-list spaced">${answered.map(requestItem).join('')}</div></details>`:''}${actions.some(a=>a.status==='accepted')?`<details class="spaced"><summary>Accepted follow-through</summary><section class="card spaced">${actions.filter(a=>a.status==='accepted').map(a=>actionCard(a)).join('')}</section></details>`:''}`;
}
function teamPage(){return `${heading('Your workspace','The people with the answers.','Invite colleagues, manage workspace access and keep responsibility clear.')}<div class="team-grid spaced"><section class="card"><h2>${escape(state.company.name)}</h2>${state.members.map(m=>`<div class="member"><div><strong>${escape(m.name)}</strong><span class="fine muted">${escape(m.email)}</span></div><div class="member-controls"><span class="chip">${m.role==='manager'?'Owner / manager':'Member'}</span>${m.active===false?'<span class="chip closed">Inactive</span>':''}${state.user.role==='manager' && m.id!==state.user.id?`<button class="link small" data-action="member-access" data-id="${m.id}">${m.active===false?'Reactivate':'Deactivate access'}</button>`:''}</div></div>`).join('')}<p class="fine muted spaced">Members share live questions, responses and decisions. Draft plans are manager-only. Deactivation ends access; authored evidence and outstanding work stay visible.</p></section><section class="card"><h2>Invite a teammate</h2>${state.user.role==='manager'?'<p class="fine muted">Create a private invitation link and share it with this person. Links expire after 72 hours and can be used once.</p><form data-form="invite" class="fields"><label>Work email<input type="email" name="email" required maxlength="254" placeholder="colleague@company.com"></label><button type="submit" class="primary">Create invitation link</button><div class="form-message" role="alert"></div></form><div id="invite-result"></div>':'<p class="muted fine">Your company manager can invite colleagues.</p>'}</section></div>`;}
function showMember(id){const m=state.members.find(m=>m.id===id);if(!m || m.id===state.user.id)return;const active=m.active!==false;openModal(active?'Deactivate workspace access?':'Reactivate workspace access?','Team / '+m.name,`<p>${active?'This member will be signed out and cannot access this workspace. Their responses and action history will be preserved. Review and reassign any outstanding work.':'This member will be able to sign in again. Review their assignments separately.'}</p><form data-form="member-access" data-id="${m.id}" data-active="${active}" class="fields"><p class="fine muted">${escape(m.name)} · ${escape(m.email)}</p><button class="primary" type="submit">${active?'Deactivate access':'Reactivate access'}</button><div class="form-message" role="alert"></div></form>`,{kind:'member',id});}
function openModal(title,kicker,body,context){
  modalContext=context;
  $('#modal').innerHTML=`<div class="modal-head"><div><p class="eyebrow">${escape(kicker)}</p><h2 id="modal-title">${escape(title)}</h2></div><button class="light small" data-action="close-modal" aria-label="Close dialog">✕</button></div><div class="modal-body">${body}</div>`;
  if(!$('#modal').open)$('#modal').showModal();
}
function showEvidence(responseId){const a=state.responses.find(r=>r.id===responseId);if(!a)return toast('This evidence is not available in your workspace.');openModal('Source response','Exact recorded evidence',`${chip(a.status)}<div class="spaced">${responseBody(a)}</div><button class="link" data-action="request" data-id="${a.requestId}">Open current request & history →</button>`,{kind:'evidence',id:responseId});}
function showRequest(id){
  const r=state.requests.find(r=>r.id===id);if(!r)return;
  requestOpen=id;if(!sample)setRoute('request',id);
  const q=state.questions.find(q=>q.id===r.questionId),history=state.responses.filter(a=>a.requestId===id),latest=history.at(-1),manager=state.user.role==='manager',canReply=q.status==='live' && (manager || r.assigneeId===state.user.id),row=brief(q.id).rows.find(row=>row.requestId===id);
  const previous=state.responses.find(a=>a.id===r.previousResponseId),suggestions=(state.suggestions?.[id] || []).map(s=>state.responses.find(r=>r.id===s.responseId)).filter(Boolean);
  openModal(r.title,'Team response / '+person(r.assigneeId),`<p class="fine muted">Owner’s question: ${escape(q.text)}</p><p class="pre">${escape(r.prompt)}</p><button class="link small" data-action="copy-link" data-kind="request" data-id="${id}">Copy request link</button>${(r.followups || []).length?`<div class="followup"><strong>Latest follow-up</strong><p class="spaced">${escape(r.followups.at(-1).text)}</p><span class="fine">${escape(r.followups.at(-1).authorName)} · ${date(r.followups.at(-1).createdAt)}</span></div>`:''}${latest?`<section class="history-item"><div class="meta">${chip(latest.requestVersion===r.version?latest.status:'update_requested')}${freshness(row)}<span>${escape(changeLabel(row))}</span></div>${responseBody(latest)}</section>`:'<div class="notice spaced">No response yet. The answer stays unknown until someone supplies facts for this check-in.</div>'}${previous?`<details><summary>Previous check-in · dated context</summary><article class="history-item">${responseBody(previous)}<p class="fine pending-refresh">This is a different check-in. Confirm scope and dates in a new response; this evidence is not automatically current.</p></article></details>`:''}${canReply && latest?.requestVersion===r.version?`<form data-form="reconfirm" data-id="${id}" data-version="${r.version}" data-previous="${latest.id}" class="reconfirm-box"><h3>Nothing has changed?</h3><p class="fine muted">Use this only after rechecking that the entire latest response still applies to this question and scope. The original observation date stays unchanged.</p><button type="submit" class="light">I rechecked: no change</button><div class="form-message" role="alert"></div></form>`:''}${canReply?`<form data-form="response" data-id="${id}" data-version="${r.version}" data-previous="${escape(latest?.id || '')}" class="fields"><h3>${latest?'What has changed?':'Your response'}</h3>${suggestions.length?`<details><summary>Possibly relevant earlier evidence (${suggestions.length})</summary><p class="fine muted">Keyword matches only. Check scope and observation time before reusing.</p>${suggestions.map(a=>`<div class="history-item"><p>${escape(a.text)}</p><span class="fine muted">${escape(a.authorName)} · ${date(a.observedAt || a.createdAt)}</span><br><button type="button" class="link small" data-action="reuse" data-id="${a.id}">Use as a starting point →</button></div>`).join('')}</details>`:''}<input type="hidden" name="reuseResponseId" value=""><label>${latest?'Updated situation':'What do you know?'}<textarea name="text" required maxlength="6000" rows="4" placeholder="State the current situation, result and uncertainty. Include enough context for the owner to understand this response on its own."></textarea></label><div class="two"><label>Reported situation<select name="status"><option value="unknown">Unknown / not yet confirmed</option><option value="on_track">On track</option><option value="at_risk">At risk</option><option value="blocked">Blocked</option></select></label><label>When was this observed? (optional)<input type="datetime-local" name="observedAt"><button type="button" class="link small" data-action="observed-now">Observed now</button><span class="helper">Leave blank if unknown. Saving is not an observation.</span></label></div><label>Decision needed (optional)<textarea name="decisionNeeded" maxlength="2000" rows="2" placeholder="What do you need the owner to decide?"></textarea></label><details><summary>Source and next step (optional)</summary><div class="fields spaced"><label>Source reference<input name="source" maxlength="1000" placeholder="Order reference, measurement, report or URL"></label><label>Next step / dependency<textarea name="nextStep" maxlength="2000" rows="2"></textarea></label></div></details><p class="fine muted">Earlier responses stay in history. Team statements are not independently verified.</p><button type="submit" class="primary">${latest?'Save updated response':'Submit response'} →</button><div class="form-message" role="alert"></div></form>`:''}${manager && q.status==='live'?`<details ${state.members.find(m=>m.id===r.assigneeId)?.active===false?'open':''}><summary>Request clarification or reassign</summary><form data-form="followup" data-id="${id}" data-version="${r.version}" class="fields"><label>Responsible person<select name="assigneeId" required>${options(r.assigneeId)}</select></label><label>What needs clarification?<textarea name="followup" required maxlength="1500" rows="3" placeholder="Ask for the specific missing fact or updated evidence."></textarea></label><button type="submit" class="light">Request an update</button><div class="form-message" role="alert"></div></form></details>`:''}${history.length?`<details><summary>Response history · ${history.length}</summary>${[...history].reverse().map(a=>`<article class="history-item">${chip(a.status)}<div class="spaced">${responseBody(a)}</div></article>`).join('')}</details>`:''}${(r.followups || []).length>1?`<details><summary>Follow-up history</summary>${r.followups.map(f=>`<div class="history-item"><p>${escape(f.text)}</p><span class="fine muted">${escape(f.authorName)} · ${date(f.createdAt)}</span></div>`).join('')}</details>`:''}${sample?'<div class="notice spaced">Illustrative sample only. Create a company to collect real responses.</div>':''}`,{kind:'request',id});
}
function showDecision(questionId,responseId=''){
  const q=state.questions.find(q=>q.id===questionId),a=state.responses.find(a=>a.id===responseId && a.questionId===questionId);if(!q)return;
  openModal(a?'Decide & assign':'Record a decision','Owner authorization',`${a?`<article class="history-item"><p class="eyebrow">Decision request / exact source</p><p>${escape(a.decisionNeeded || a.text)}</p><p class="fine muted">${escape(a.authorName)} · ${date(a.createdAt)}</p><details><summary>Inspect source response</summary><div class="spaced">${responseBody(a)}</div></details></article>`:'<p class="muted fine">Record your judgment and, optionally, assign a concrete next step.</p>'}<form data-form="decision" data-id="${q.id}" data-response="${escape(a?.id || '')}" class="fields"><label>Decision or direction<textarea name="text" required maxlength="3000" rows="3" placeholder="What did you decide, and why?"></textarea></label><label class="checkbox-label"><input type="checkbox" name="assignAction" data-toggle="assignment"> Assign a next step</label><fieldset class="assignment-fields fields" hidden disabled><legend>Authorized follow-through</legend><label>Action<input name="actionTitle" maxlength="200" required placeholder="Confirm carrier booking for B17"></label><label>Expected result<textarea name="expectedResult" maxlength="2000" required rows="2" placeholder="What result should the responsible person report back?"></textarea></label><div class="two"><label>Responsible person<select name="assigneeId" required>${options()}</select></label><label>Due date (optional)<input name="dueDate" type="date"></label></div></fieldset><p class="fine muted">${a?'This decision will link to this exact response. ':''}Saving with an assigned next step creates a team action. A decision does not automatically resolve the underlying risk.</p><button type="submit" class="primary">Record decision</button><div class="form-message" role="alert"></div></form>`,{kind:'decision',questionId,responseId});
}
function showAction(id){
  const a=(state.actions || []).find(a=>a.id===id);if(!a)return;
  const q=state.questions.find(q=>q.id===a.questionId),d=state.decisions.find(d=>d.id===a.decisionId),manager=state.user.role==='manager',allowed=manager || a.assigneeId===state.user.id;
  const choices=a.status==='accepted'?(manager?['open']:[]):['open','in_progress','blocked','reported_done',...(manager && a.status==='reported_done'?['accepted']:[])];
  openModal(a.title,'Follow-through / '+person(a.assigneeId),`<p class="fine muted">${escape(q?.text || 'Company question')}${q?.status==='closed'?' · Question closed; this action remains tracked.':''}</p><div class="row">${chip(a.status)}${isOverdue(a)?'<span class="chip at_risk">Past due date</span>':''}</div><p class="pre spaced"><strong>Expected result:</strong> ${escape(a.expectedResult)}</p><p class="fine muted">${a.dueDate?'Due '+date(a.dueDate)+' · ':''}Assigned by ${escape(a.authorName)} · ${date(a.createdAt)}</p>${d?`<details><summary>Decision and supporting evidence</summary><p class="pre spaced">${escape(d.text)}</p>${(d.responseIds || []).map(id=>`<button class="link small" data-action="evidence" data-response="${id}">Inspect linked source response ↗</button>`).join('')}</details>`:''}${allowed && choices.length?`<form data-form="action-update" data-id="${a.id}" data-version="${a.version}" class="fields"><h3>${a.status==='reported_done' && manager?'Review the reported result':'Update this action'}</h3>${manager?`<label>Responsible person<select name="assigneeId" required>${options(a.assigneeId)}</select><span class="helper">Changing this assigns the action to that person when you save.</span></label>`:''}<label>State<select name="status">${choices.map(status=>`<option value="${status}" ${status===a.status?'selected':''}>${escape(status==='open' && a.status==='accepted'?'Reopen action':labels[status])}</option>`).join('')}</select></label><label>${a.status==='reported_done' && manager?'Review note / acceptance reason':'What changed?'}<textarea name="note" required maxlength="3000" rows="3" placeholder="Describe progress, a blocker, or the reported result."></textarea></label><label>Source reference (optional)<input name="source" maxlength="1000" placeholder="Booking reference, measurement, report or URL"></label><p class="fine muted">Only a manager can accept a reported result. Acceptance records their judgment, not a verified KPI outcome.</p><button class="primary" type="submit">Save action update</button><div class="form-message" role="alert"></div></form>`:''}<section class="spaced"><h3>Action history</h3>${(a.updates || []).length?[...a.updates].reverse().map(u=>`<article class="history-item">${chip(u.status)}<p class="pre spaced">${escape(u.note)}</p><p class="fine muted">${escape(u.authorName)} · ${date(u.createdAt)}${u.source?'<br>Source: '+escape(u.source):''}</p></article>`).join(''):'<p class="fine muted">Assigned; no updates have been recorded yet.</p>'}</section>`,{kind:'action',id});
}
function showCheckIn(id){const q=state.questions.find(q=>q.id===id);if(!q)return;openModal('Start the next check-in','Reuse the plan · collect current facts',`<p class="muted fine">The previous prompts and assignees become a draft for your review. Previous responses remain dated context and do not count as answers to this new check-in.</p><form data-form="check-in" data-id="${q.id}" data-version="${q.version}" class="fields"><label>Question for this check-in<textarea name="text" required maxlength="1200" rows="3">${escape(q.text)}</textarea></label><label>New scope / reporting period<textarea name="context" required maxlength="3000" rows="3" placeholder="Specify the new dates, orders or project scope. Review any dates carried in the question above."></textarea></label><label>Responses needed by (optional)<input name="dueDate" type="date"></label><p class="fine muted">Evidence review policy: ${q.freshnessDays || 7} days. You can adjust it in the draft.</p><button type="submit" class="primary">Create next draft →</button><div class="form-message" role="alert"></div></form>`,{kind:'check-in',id});}
function setRoute(kind,id){if(!sample)history.replaceState(null,'',location.pathname+location.search+(kind?'#'+kind+'='+encodeURIComponent(id):''));}
function applyRoute(hash=location.hash){
  const params=new URLSearchParams(hash.slice(1)),requestId=params.get('request'),questionId=params.get('question');
  if(requestId){const r=state.requests.find(r=>r.id===requestId);if(r){selected=r.questionId;screen='questions';render();showRequest(r.id);return true;}}
  if(questionId && state.questions.some(q=>q.id===questionId)){selected=questionId;screen='questions';render();return true;}
  if(requestId || questionId)toast('This item is not available in your company workspace.');return false;
}
function briefingText(q){const b=brief(q.id);return [q.text,q.context || '',`Check-in ${q.round || 1} · Copied ${date(new Date().toISOString())}`,`Responses received: ${b.answered}/${b.total}. Reporting coverage is not business performance.`,`Evidence review policy: ${q.freshnessDays || 7} days.`,...b.rows.map(row=>`${row.title} — ${labels[row.state] || row.state}\n${row.response?row.response.text:'No response yet.'}${row.current?'':'\nNot a current response; an answer or update is needed.'}${row.response?`\nBy ${row.response.authorName}; observed ${date(row.response.observedAt)}${row.response.confirmedAt?'; rechecked '+date(row.response.confirmedAt):''}; recorded ${date(row.response.createdAt)}\nSource: ${row.response.source || 'Team statement'}${row.response.decisionNeeded?'\nDecision requested: '+row.response.decisionNeeded:''}${row.response.nextStep?'\nNext step: '+row.response.nextStep:''}`:''}`),'FOLLOW-THROUGH',...b.actions.map(a=>`${a.title} — ${labels[a.status]}\nResponsible: ${person(a.assigneeId)}; due ${date(a.dueDate)}\nExpected: ${a.expectedResult}`),'OWNER DECISIONS',...b.decisions.map(d=>`${d.text}\n${d.authorName} · ${date(d.createdAt)}`),'Source references are recorded, not independently verified.'].filter(Boolean).join('\n\n');}
async function copyText(text,title='Copy text'){try{await navigator.clipboard.writeText(text);toast('Copied to your clipboard. Nothing was sent.');}catch{openModal(title,'Local copy only',`<p class="fine muted">Select and copy the text below. Nothing is sent to another application.</p><textarea id="copy-output" rows="12" readonly aria-label="Text to copy">${escape(text)}</textarea>`,{kind:'copy'});$('#copy-output').select();}}
function snapshotForm(form){return {kind:form.dataset.form,id:form.dataset.id,data:Object.fromEntries(new FormData(form)),plan:[...form.querySelectorAll('.plan-card')].map(card=>Object.fromEntries([...card.querySelectorAll('[data-field]')].map(el=>[el.dataset.field,el.value])))};}
function restoreForm(saved){const form=[...document.querySelectorAll('form[data-form]')].find(f=>f.dataset.form===saved.kind && f.dataset.id===saved.id);if(!form)return false;for(const [name,value] of Object.entries(saved.data)){const el=form.elements[name];if(!el)continue;if(el.type==='checkbox'){el.checked=Boolean(value);el.dispatchEvent(new Event('change',{bubbles:true}));}else if(el.tagName!=='SELECT' || [...el.options].some(o=>o.value===value))el.value=value;}if(saved.plan.length && saved.kind==='plan'){const currentIds=new Set(state.requests.filter(r=>r.questionId===saved.id).map(r=>r.id));$('#plan-requests').innerHTML=saved.plan.map(r=>({...r,id:currentIds.has(r.id)?r.id:''})).map(planCard).join('');}return true;}
async function recoverForm(form){const saved=snapshotForm(form),context=modalContext;await refresh(false);render();if($('#modal').open && context){if(context.kind==='request')showRequest(context.id);if(context.kind==='action')showAction(context.id);if(context.kind==='check-in')showCheckIn(context.id);if(context.kind==='decision')showDecision(context.questionId,context.responseId);if(context.kind==='member')showMember(context.id);}if(restoreForm(saved))toast('Latest record loaded. Your draft is preserved; review the new context before saving.');else openModal('Your unsaved draft','Record changed',`<p class="fine muted">The record now has a different state. Your draft is preserved below for copying; review the current record before continuing.</p><textarea rows="12" readonly aria-label="Preserved draft">${escape(JSON.stringify(saved.data,null,2))}</textarea>`,{kind:'copy'});}
document.addEventListener('change',event=>{if(event.target.matches('[data-toggle="assignment"]')){const fieldset=event.target.closest('form').querySelector('.assignment-fields');fieldset.hidden=!event.target.checked;fieldset.disabled=!event.target.checked;event.target.closest('form').querySelector('button[type="submit"]').textContent=event.target.checked?'Record decision & assign action':'Record decision';}});
document.addEventListener('click',async event=>{
  const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;
  try {
    if(action==='auth-mode'){authMode=button.dataset.mode;renderAuth();}
    if(action==='sample'){sample=true;state=sampleState();selected='sample-question';screen='questions';render();}
    if(action==='exit-sample'){sample=false;state=null;selected=null;$('#modal').close();modalContext=null;renderAuth();}
    if(action==='nav'){screen=button.dataset.screen;selected=null;setRoute();await refresh(false);render();}
    if(action==='question'){selected=button.dataset.id;screen='questions';$('#modal').close();modalContext=null;setRoute('question',selected);await refresh(false);render();window.scrollTo(0,0);}
    if(action==='back'){selected=null;setRoute();render();}
    if(action==='request'){await refresh(false);showRequest(button.dataset.id);}
    if(action==='evidence'){showEvidence(button.dataset.response);}
    if(action==='member-access'){await refresh(false);showMember(button.dataset.id);}
    if(action==='action-detail'){await refresh(false);showAction(button.dataset.id);}
    if(action==='decide'){await refresh(false);showDecision(button.dataset.question,button.dataset.response);}
    if(action==='check-in'){await refresh(false);showCheckIn(button.dataset.id);}
    if(action==='starter'){const field=$('form[data-form="ask"] textarea[name="text"]');if(field.value.trim())return toast('Clear your question first to choose a starter.');field.value=starters[Number(button.dataset.index)][1];field.focus();}
    if(action==='observed-now'){const now=new Date();button.closest('form').elements.observedAt.value=new Date(now.getTime()-now.getTimezoneOffset()*60000).toISOString().slice(0,16);toast('Observation time set to now by you.');}
    if(action==='close-modal'){$('#modal').close();requestOpen=null;modalContext=null;setRoute(selected?'question':null,selected);}
    if(action==='refresh'){
      const saved=[...document.querySelectorAll('form[data-form]')].map(snapshotForm),context=modalContext;
      await refresh();
      if($('#modal').open && context){if(context.kind==='request')showRequest(context.id);if(context.kind==='action')showAction(context.id);if(context.kind==='check-in')showCheckIn(context.id);if(context.kind==='decision')showDecision(context.questionId,context.responseId);if(context.kind==='member')showMember(context.id);}
      saved.forEach(restoreForm);toast(sample?'This is a sample briefing.':'Workspace refreshed. Your form drafts are preserved.');
    }
    if(action==='logout'){await api('/logout',{});state=null;selected=null;screen='questions';$('#modal').close();modalContext=null;renderAuth();}
    if(action==='add-request'){const cards=document.querySelectorAll('.plan-card');if(cards.length>=8)return toast('Use up to eight focused requests.');$('#plan-requests').insertAdjacentHTML('beforeend',planCard({title:'',role:'',prompt:'',assigneeId:null},cards.length));}
    if(action==='remove-request'){if(document.querySelectorAll('.plan-card').length<=1)return toast('Keep at least one request.');button.closest('.plan-card').remove();}
    if(action==='transition'){
      if(sample)return toast('Create your company to use this workflow.');
      const q=state.questions.find(q=>q.id===button.dataset.id);button.disabled=true;
      try{await api(`/questions/${q.id}/${button.dataset.transition}`,{expectedVersion:q.version});await refresh();toast(button.dataset.transition==='close'?'Question closed. Existing follow-through remains tracked.':'Question reopened.');}finally{button.disabled=false;}
    }
    if(action==='copy-link'){
      if(sample)return toast('Sample links are illustrative. Create a company to share authenticated links.');
      await copyText(location.origin+location.pathname+'#'+button.dataset.kind+'='+encodeURIComponent(button.dataset.id),'Copy workspace link');
    }
    if(action==='copy-briefing'){const q=state.questions.find(q=>q.id===button.dataset.id);await copyText((sample?'ILLUSTRATIVE SAMPLE — NOT REAL COMPANY DATA\n\n':'')+briefingText(q),'Copy briefing');}
    if(action==='copy-invite'){await copyText($('#invitation-url').value,'Copy invitation link');}
    if(action==='reuse'){
      const a=state.responses.find(r=>r.id===button.dataset.id),form=button.closest('form');
      if(form.elements.text.value.trim())return toast('Clear your response text before using an earlier response.');
      form.elements.text.value=a.text;form.elements.source.value=a.source || '';form.elements.reuseResponseId.value=a.id;
      if(a.observedAt){const d=new Date(a.observedAt);form.elements.observedAt.value=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
      form.elements.status.value='unknown';toast('Earlier text added. Check scope, observation date and current status before submitting.');
    }
    if(action==='recover-form' || action==='recover-response'){await recoverForm(button.closest('form'));}
  }catch(error){toast(error.message);}
});
document.addEventListener('submit',async event=>{
  const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();
  if(sample)return toast('This is an illustrative sample. Create a company to save changes.');
  const data=Object.fromEntries(new FormData(form)),kind=form.dataset.form,message=form.querySelector('.form-message'),buttons=[...form.querySelectorAll('button')];
  if(message)message.innerHTML='';buttons.forEach(b=>b.disabled=true);
  const submitter=event.submitter,oldLabel=submitter?.textContent;if(submitter)submitter.textContent=kind==='ask'?'Building your plan…':'Saving…';
  try{
    if(kind==='auth'){
      const result=await api('/'+(authMode==='signup'?'signup':authMode==='join'?'join':'login'),authMode==='join'?{...data,token:joinToken}:data);
      state=result;selected=null;screen=result.user.role==='manager'?'questions':'requests';await refresh(false);
      if(!applyRoute(initialRoute)){setRoute();render();}
    }
    if(kind==='ask'){const result=await api('/questions',{...data,freshnessDays:Number(data.freshnessDays || 7)});selected=result.question.id;setRoute('question',selected);await refresh();window.scrollTo(0,0);}
    if(kind==='plan'){
      const requests=[...form.querySelectorAll('.plan-card')].map(card=>Object.fromEntries([...card.querySelectorAll('[data-field]')].map(el=>[el.dataset.field,el.value])));
      const launch=submitter?.value==='launch';if(launch && requests.some(r=>!r.assigneeId))throw new Error('Choose a responsible person for every request. You can assign yourself.');
      const result=await api('/questions/'+form.dataset.id,{...data,freshnessDays:Number(data.freshnessDays || 7),expectedVersion:Number(form.dataset.version),requests},'PATCH');
      form.dataset.version=result.question.version;
      if(launch)await api(`/questions/${form.dataset.id}/launch`,{expectedVersion:result.question.version});
      await refresh();toast(launch?'Requests launched. Copy a question link to share in your existing team chat.':'Draft saved.');
    }
    if(kind==='response'){
      await api(`/requests/${form.dataset.id}/responses`,{...data,observedAt:data.observedAt?new Date(data.observedAt).toISOString():null,expectedVersion:Number(form.dataset.version),expectedResponseId:form.dataset.previous || null});
      $('#modal').close();modalContext=null;setRoute(selected?'question':null,selected);await refresh();toast('Response saved. Your evidence is now in the briefing.');
    }
    if(kind==='reconfirm'){
      await api(`/requests/${form.dataset.id}/reconfirm`,{expectedVersion:Number(form.dataset.version),expectedResponseId:form.dataset.previous || null});
      await refresh();showRequest(form.dataset.id);toast('Explicit recheck recorded. The original observation date is preserved.');
    }
    if(kind==='followup'){
      await api(`/requests/${form.dataset.id}`,{...data,expectedVersion:Number(form.dataset.version)},'PATCH');
      await refresh();showRequest(form.dataset.id);toast('Update requested. Earlier evidence and concerns remain visible.');
    }
    if(kind==='decision'){
      const body={text:data.text,responseIds:form.dataset.response?[form.dataset.response]:[]};
      if(data.assignAction)body.action={title:data.actionTitle,expectedResult:data.expectedResult,assigneeId:data.assigneeId,dueDate:data.dueDate || null};
      await api(`/questions/${form.dataset.id}/decisions`,body);$('#modal').close();modalContext=null;await refresh();toast(data.assignAction?'Decision recorded and next step assigned.':'Decision recorded with its source references.');
    }
    if(kind==='action-update'){
      await api(`/actions/${form.dataset.id}`,{...data,expectedVersion:Number(form.dataset.version)},'PATCH');await refresh();showAction(form.dataset.id);toast(data.status==='accepted'?'Manager acceptance recorded.':'Action update saved.');
    }
    if(kind==='check-in'){
      const result=await api(`/questions/${form.dataset.id}/check-ins`,{...data,expectedVersion:Number(form.dataset.version)});
      selected=result.question.id;screen='questions';$('#modal').close();modalContext=null;setRoute('question',selected);await refresh();window.scrollTo(0,0);toast('New check-in draft created. Review scope, prompts and assignments before launch.');
    }
    if(kind==='member-access'){await api(`/members/${form.dataset.id}`,{active:form.dataset.active!=='true',expectedActive:form.dataset.active==='true'},'PATCH');$('#modal').close();modalContext=null;await refresh();toast(form.dataset.active==='true'?'Access deactivated. Review outstanding assignments on the owner desk.':'Member access restored.');}
    if(kind==='invite'){
      const result=await api('/invites',data);const url=location.origin+'/#join='+result.invite.token;
      $('#invite-result').innerHTML=`<div class="invite-link"><strong class="fine">Share with ${escape(result.invite.email)}</strong><input id="invitation-url" aria-label="Invitation link" readonly value="${escape(url)}"><button type="button" class="light small" data-action="copy-invite">Copy link</button><p class="fine muted spaced">Expires ${date(result.invite.expiresAt)}. Creating another invitation for this address replaces this one. No email has been sent.</p></div>`;form.reset();
    }
  }catch(error){
    if(message)message.innerHTML=`<div class="error">${escape(error.message)}${error.status===409?'<br><button type="button" class="light small spaced" data-action="recover-form">Load latest record & keep my draft</button>':''}</div>`;
    else toast(error.message);
  }finally{buttons.forEach(b=>b.disabled=false);if(submitter)submitter.textContent=oldLabel;}
});
