  const decisions=[{id:'sample-decision',questionId:q.id,text:'Prepare a second collection, subject to production and quality release confirmation.',authorName:'Alex Morgan',createdAt:'2026-09-25T09:30:00Z',responseIds:['sample-a2']}];
