async function start(){try{const session=await api('/session',undefined,'GET');if(session.user && joinToken){state=session;$('#app').innerHTML=`<header>${brand}</header><main class="page"><h1>You’re already signed in.</h1><p>This invitation is for a new member account. Sign out before accepting it.</p><button class="primary" data-action="logout">Sign out to open invitation</button></main>`;return;}if(session.user){state=session;screen=session.user.role==='manager'?'questions':'requests';await refresh(false);if(!applyRoute())render();}else renderAuth();}catch(error){renderAuth();toast('Could not connect. Please reload to try again.');}}
window.addEventListener('hashchange',()=>{if(state && !sample)applyRoute();});
// Refresh only read-only views. Never replace an open dialog or any form draft.
refreshTimer=setInterval(async()=>{if(!state || sample || document.hidden || $('#modal').open || document.activeElement?.closest('form'))return;const q=state.questions.find(q=>q.id===selected);if(screen==='team' || !selected || q?.status==='draft' || [...document.querySelectorAll('form textarea')].some(el=>el.value.trim()))return;try{const previous=JSON.stringify(state);await refresh(false);if(JSON.stringify(state)!==previous)render();}catch{}},20000);
start();
